function FormStatus({ status }: { status: SubmitState }) {
  if (status === 'loading') return <div data-testid="status-form-loading" className="mt-4 flex items-center gap-2 text-xs text-[#a26e3e]"><span className="h-2 w-2 animate-pulse rounded-full bg-[#d6a365]" />Preparing your inquiry locally…</div>;
  if (status === 'success') return <div data-testid="status-form-success" className="mt-4 border border-[#46766a] bg-[#e1eee7] p-4 text-sm text-[#183634]"><Check size={16} className="mb-2 text-[#46766a]" /><b>Your inquiry is ready to connect.</b><p className="mt-1 text-xs text-[#46766a]">No message has been sent. A backend or CRM endpoint can be connected to this form.</p></div>;
  if (status === 'error') return <div data-testid="status-form-error" className="mt-4 flex items-center gap-2 text-xs text-[#a33e35]"><CircleAlert size={15} />Please complete the required fields and try again.</div>;
  return null;
}

function Field({ label, name, type = 'text', required = true, options, placeholder }: { label: string; name: string; type?: string; required?: boolean; options?: string[]; placeholder?: string }) {
  const common = { name, required, 'data-testid': `input-${name}`, className: 'mt-2 w-full border-b border-[#183634]/25 bg-transparent px-0 py-3 text-sm outline-none transition-colors placeholder:text-[#183634]/35 focus:border-[#a26e3e]' };
  return <label className="block text-[10px] font-bold uppercase tracking-[.12em] text-[#183634]/60">{label}{required && <span className="text-[#a26e3e]"> *</span>}{options ? <select {...common} defaultValue=""><option value="" disabled>Select one</option>{options.map(x => <option key={x}>{x}</option>)}</select> : <input {...common} type={type} placeholder={placeholder} />}</label>;
}

function InquiryForm({ financing = false }: { financing?: boolean }) {
  const [status, setStatus] = useState<SubmitState>('idle');
  function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget; setStatus('loading'); window.setTimeout(() => setStatus(form.checkValidity() ? 'success' : 'error'), 550); }
  const fields = financing ? [
    ['name', 'Name', 'text'], ['whatsapp', 'WhatsApp', 'tel'], ['cnic', 'CNIC', 'text'], ['income', 'Monthly Income', 'text'], ['employment', 'Employment Type', 'text'], ['property', 'Preferred Property', 'text'], ['location', 'Preferred Location', 'text'], ['budget', 'Estimated Budget', 'text'],
  ] : [
    ['name', 'Full Name', 'text'], ['phone', 'Phone / WhatsApp', 'tel'], ['email', 'Email', 'email'], ['interest', 'Interest', 'select'], ['budget', 'Budget', 'select'], ['location', 'Preferred Location', 'text'],
  ];
  const interest = ['Residential', 'Commercial', 'Plot/Land', 'Investment', 'Emaar', 'Home Financing'];
  const budgets = ['Under 1 Crore', '1–3 Crore', '3–5 Crore', '5 Crore+', 'Not Decided'];
  return <form noValidate onSubmit={submit} data-testid={`form-${financing ? 'financing' : 'property-inquiry'}`} className="grid gap-x-8 gap-y-7">
    <div className="grid gap-x-8 gap-y-7 md:grid-cols-2">{fields.map(([name, label, type]) => type === 'select' ? <Field key={name} name={name} label={label} options={name === 'interest' ? interest : budgets} /> : <Field key={name} name={name} label={label} type={type} />)}</div>
    {!financing && <Field name="message" label="Message" required={false} placeholder="Tell us what you are looking for…" />}
    <button type="submit" data-testid={`button-submit-${financing ? 'financing' : 'inquiry'}`} className="mt-2 flex w-fit items-center gap-4 bg-[#183634] px-6 py-4 text-[10px] font-bold uppercase tracking-[.14em] text-[#eee9df] transition-colors hover:bg-[#a26e3e]">{financing ? 'Check My Options' : 'Request a Call Back'}<Send size={15} /></button>
    <FormStatus status={status} />
  </form>;
}

